- diff = wr_bin_next - rd_bin_sync (LOG_DEPTH+1 bits)
- full = (diff == 2**LOG_DEPTH)

Actually simpler: full = (wr_bin_next[MSB] != rd_bin_sync[MSB]) && (wr_bin_next[MSB-1:0] == rd_bin_sync[MSB-1:0]).

