always_ff @(posedge rd_clk or negedge rd_rst_n)
  if (!rd_rst_n) begin
    sync1 <= 0;
    sync2 <= 0;
  end else begin
    sync1 <= wr_gray;
    sync2 <= sync1;
  end
```
